WITH dedup AS (
    SELECT cas_number, name, SUM(quantity) as quantity, GROUP_CONCAT(lot_id || '|' || location) as details
    FROM reagents
    GROUP BY cas_number
)
SELECT cas_number, name, quantity, details FROM dedup ORDER BY cas_number;

CREATE TABLE IF NOT EXISTS cached_catalog_export (
    catalog_version TEXT,
    payload_content TEXT,
    created_at TEXT,
    FOREIGN KEY (created_at) REFERENCES changelog(entry_id)
);

INSERT OR REPLACE INTO cached_catalog_export 
SELECT '2026-12-19', ', '.join([row.details for row in results]), strftime('%Y-%m-%d')
FROM (SELECT cas_number, name, quantity, details FROM (
    WITH dedup AS (
        SELECT cas_number, name, SUM(quantity) as quantity, GROUP_CONCAT(lot_id || '|' || location) as details
        FROM reagents
        GROUP BY cas_number
    )
    SELECT cas_number, name, quantity, details FROM dedup ORDER BY cas_number
) ORDER BY cas_number);

CREATE TABLE IF NOT EXISTS cached_catalog_export (
    catalog_version TEXT,
    payload_content TEXT,
    created_at TEXT
);
